function modelDocument(index: number): LibraryModel["model_document"] {
  if (index >= 2 && index <= 6) return clone(actualLtxModels[index - 2]!.model_document);
  const document = clone(index === 0 ? actualModelDocument36 : index === 1 ? actualModelDocument37 : actualModelDocumentSeed);
  if (index < 2) return document;
  const publisher = index % 2 === 0 ? "deepseek-ai" : "inclusionai";
  const slug = index % 2 === 0 ? `deepseek-v4-flash-${index + 1}` : `ling-3-flash-${index + 1}`;
  const title = index % 2 === 0 ? `DeepSeek V4 Flash ${index + 1}` : `Ling 3 Flash ${index + 1}`;
  document.identity = {...document.identity, publisher, slug, version: `catalog-${index + 1}`, variant: `schema2-${index + 1}`, model: {...document.identity.model, publisher, slug, title}, family: {...document.identity.family, publisher, slug: slug.split("-")[0]!, title}};
  document.metadata = {...document.metadata, description: `${title} canonical ModelDefinition from the Controller catalog corpus.`};
  return document;
}

function model(index: number, recipes: LibraryRecipeSummary[]): LibraryModel {
  const document = modelDocument(index);
  const actual = index >= 2 && index <= 6 ? actualLtxModels[index - 2]!.model : undefined;
  if (actual) return {...clone(actualLtxModels[index - 2]!), model_document: document, recipes};
  return {page_local: true, model: {kind: "model", publisher: document.identity.publisher, slug: document.identity.slug, content_sha256: digest(`m${index}`)}, model_document: document, model_capabilities: {...document.capabilities, state: "declared"} as LibraryModel["model_capabilities"], recipes};
}

const syntheticModelTargets = [0, 1, ...Array.from({length: 72}, (_, offset) => offset + 7)];
function syntheticModelTarget(recipeIndex: number): number { return syntheticModelTargets[(recipeIndex - actualLtxRecipes.length) % syntheticModelTargets.length]!; }

function recipe(index: number): LibraryRecipeSummary {
  if (index < actualLtxRecipes.length) return clone(actualLtxRecipes[index]!);
  const id = index === 0 ? actualRecipeDocumentSeed.identity.slug : `recipe-${index + 1}`;
  const title = index === 0 ? actualRecipeDocumentSeed.metadata.title : index === 1 ? "Ling 3.0 Flash auxiliary" : `Catalog Recipe ${index + 1}`;
  const definition = clone(actualRecipeDocumentSeed);
  if (index === 0) return {capabilities: [], content_sha256: digest(`r${index}`), description: definition.metadata.description, installation_returned_count: 0, installation_total_count: 0, installations: [], installations_truncated: false, publisher: definition.identity.publisher, reasons: [], recipe_capabilities: {schema_version: 2, state: "declared", facts: []}, recipe_document: definition, recipe_id: id, recipe_revision_id: revisionId(index), run_returned_count: 0, run_total_count: 0, runs: [], runs_truncated: false, slug: id, title, topology_name: definition.topology.name};
  definition.identity = {...definition.identity, slug: id};
  definition.metadata = {...definition.metadata, title, description: `${title} canonical RecipeDefinition from the Controller catalog corpus.`};
  const modelIndexes = index === 4 ? [0, 1] : [syntheticModelTarget(index)];
  definition.models = modelIndexes.map((modelIndex, modelPosition) => {
    const source = actualRecipeDocumentSeed.models[modelPosition % actualRecipeDocumentSeed.models.length]!;
    const modelDoc = modelDocument(modelIndex);
    return {...source, id: modelPosition === 0 ? "primary" : `auxiliary-${modelPosition}`, model: {...source.model, publisher: modelDoc.identity.publisher, slug: modelDoc.identity.slug, content_sha256: digest(`m${modelIndex}`)}};
  });
  return {capabilities: ["chat"], content_sha256: digest(`r${index}`), description: definition.metadata.description, installation_returned_count: 0, installation_total_count: 0, installations: [], installations_truncated: false, publisher: definition.identity.publisher, reasons: [], recipe_capabilities: {schema_version: 2, state: "declared", facts: []}, recipe_document: definition, recipe_id: id, recipe_revision_id: revisionId(index), run_returned_count: 0, run_total_count: 0, runs: [], runs_truncated: false, slug: id, title, topology_name: definition.topology.name};
}

export function libraryRecipeSummary(input: Partial<LibraryRecipeSummary> & Pick<LibraryRecipeSummary, "recipe_id" | "slug" | "title">): LibraryRecipeSummary {
  const base = recipe(0);
  return {...base, ...input, recipe_document: {...base.recipe_document, metadata: {...base.recipe_document.metadata, title: input.title ?? base.title, description: input.description ?? base.description}, identity: {...base.recipe_document.identity, slug: input.slug}}};
}

const recipes = Array.from({length: 85}, (_, index) => recipe(index));
const models = Array.from({length: 92}, (_, index) => {
  if (index >= 2 && index <= 5) return model(index, [recipes[index - 2]!]);
  if (index === 6) return model(index, recipes.slice(0, actualLtxRecipes.length));
  if (index >= 79) return model(index, []);
  const assigned = recipes.slice(actualLtxRecipes.length).filter((_, recipeIndex) => {
    const catalogIndex = recipeIndex + actualLtxRecipes.length;
    return syntheticModelTarget(catalogIndex) === index;
  });
  if (index === 1) assigned.unshift(recipes[4]!);
  return model(index, assigned);
});

